```tsx
// Pagination.tsx
import React from "react";

type PaginationProps = {
  totalItems: number;
  pageSize: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  siblingCount?: number; // pages shown on each side of the current page
};

const range = (start: number, end: number): number[] =>
  Array.from({ length: Math.max(0, end - start + 1) }, (_, i) => start + i);

export function getPageItems(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): (number | "ellipsis")[] {
  // Always at least one page, so zero results and exactly one page both give [1].
  const total = Math.max(1, totalPages);
  if (total === 1) return [1];

  // first + last + current + 2 siblings + 2 ellipses
  const maxVisible = siblingCount * 2 + 5;
  if (total <= maxVisible) return range(1, total);

  const left = Math.max(currentPage - siblingCount, 2);
  const right = Math.min(currentPage + siblingCount, total - 1);

  const items: (number | "ellipsis")[] = [1];
  if (left > 2) items.push("ellipsis");
  items.push(...range(left, right));
  if (right < total - 1) items.push("ellipsis");
  items.push(total);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(1, currentPage), totalPages);
  const items = getPageItems(totalPages, page, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(page - 1)}
            disabled={page <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {items.map((item, i) =>
          item === "ellipsis" ? (
            <li key={`e${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
              >
                {item}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(page + 1)}
            disabled={page >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
```

**Single-page behavior**: with `totalItems = 10` and `pageSize = 10`, `totalPages` is 1, so `getPageItems` returns `[1]`. The component renders one button, "1", marked `aria-current="page"`, and both Previous and Next are disabled.

**Quick tests** (Jest/Vitest):

```ts
import { getPageItems } from "./Pagination";

test("exactly one page shows only page 1", () => {
  expect(getPageItems(1, 1)).toEqual([1]);
});
test("zero results still shows page 1", () => {
  expect(getPageItems(0, 1)).toEqual([1]);
});
test("small page counts show all pages", () => {
  expect(getPageItems(5, 3)).toEqual([1, 2, 3, 4, 5]);
});
test("large page counts collapse with ellipses", () => {
  expect(getPageItems(20, 10)).toEqual([1, "ellipsis", 9, 10, 11, "ellipsis", 20]);
});
```

Design choices:
- `currentPage` is clamped to the valid range, so a stale page number after the result set shrinks won't break the UI.
- Zero results are treated as one page, so the control never renders empty. If you'd rather hide the control in that case, return `null` when `totalItems === 0`.
- The current page's button is disabled, which avoids redundant `onPageChange` calls.

